import{_ as a,o as e,a as d,b as i}from"./app.UgfkfLuP.js";const n=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"数据搬运导览","link":"/api/SIMD-API/c_api/data_move_guide/data_move_guide"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/data_move_guide/data_move_guide.md","filePath":"api/SIMD-API/c_api/data_move_guide/data_move_guide.md","outlineHeaders":[{"level":2,"title":"阅读路线","slug":"阅读路线","link":"#阅读路线"},{"level":2,"title":"按数据通路选择","slug":"按数据通路选择","link":"#按数据通路选择"},{"level":2,"title":"接口选择原则","slug":"接口选择原则","link":"#接口选择原则"}],"lastUpdated":1790563388000}'),l={name:"api/SIMD-API/c_api/data_move_guide/data_move_guide.md"};function _(r,t,o,h,s,c){return e(),d("div",null,[...t[0]||(t[0]=[i('<div><article class="markdown-body"><h1>数据搬运导览</h1><p>本章介绍如何根据源、目的存储单元、数据排布和随路处理需求选择C API数据搬运接口，并以NPU架构版本3510的数据通路和接口能力为例进行说明。其他架构的产品支持情况和接口能力以具体接口文档为准。开发者需要显式管理地址、搬运参数、配置状态和流水同步。使用本章介绍的接口时，除接口文档另有说明外，均可包含头文件<code>c_api/asc_simd.h</code>。</p><h2 id="阅读路线">阅读路线<a class="header-anchor" href="#阅读路线">​</a></h2><ol><li>阅读<a href="overview/overview.html">概览</a>，了解存储层级、接口分类以及PIPE_MTE1、PIPE_MTE2、PIPE_MTE3、PIPE_FIX和PIPE_V的分工。</li><li>阅读<a href="overview/data_move_concept.html">数据搬运概念</a>，区分连续、高维切分、多维切片、非对齐、随路转换、矩阵分形和NDDMA等搬运形态。</li><li>阅读<a href="overview/data_path.html">数据通路</a>，按源、目的存储单元确认NPU架构版本3510是否存在直达通路，并查找对应C接口。</li><li>根据下表进入具体通路章节，核对每种模式的参数单位、前置配置和同步要求。</li><li>编码前检查<a href="overview/overall_constraints.html">总体约束说明</a>，并以具体接口文档中的产品支持、参数取值和约束为准。</li></ol><h2 id="按数据通路选择">按数据通路选择<a class="header-anchor" href="#按数据通路选择">​</a></h2><table><thead><tr><th>数据通路</th><th>NPU架构版本3510支持的主要能力</th><th>详细说明</th></tr></thead><tbody><tr><td>GM与L1/L0</td><td>GM到L1连续/切分、二维分形、ND2Nz、DN2Nz、非对齐；L0C到GM随路处理</td><td><a href="gm_l1_or_l0_data_move.html">GM与L1/L0数据搬运</a></td></tr><tr><td>GM与UB</td><td>双向连续/切分、双向非对齐、GM到UB五维NDDMA</td><td><a href="gm_ub_data_move.html">GM与UB数据搬运</a></td></tr><tr><td>L1与L0</td><td>L1到L0A/L0B二维、三维、转置和MX；L0C到L1随路处理</td><td><a href="l1_l0_data_move.html">L1与L0数据搬运</a></td></tr><tr><td>L1/L0C与UB</td><td>L1到UB、UB到L1、L0C到UB随路处理及双目标写入</td><td><a href="l1_or_l0c_ub_data_move.html">L1/L0C与UB数据搬运</a></td></tr><tr><td>L1到BiasTable</td><td>连续或高维切分bias搬运，支持指定类型转换</td><td><a href="l1_bias_table_data_move.html">L1到BiasTable数据搬运</a></td></tr><tr><td>L1到Fixpipe Buffer</td><td>连续或高维切分装载量化、ReLU参数</td><td><a href="l1_fixpipe_data_move.html">L1到Fixpipe Buffer数据搬运</a></td></tr><tr><td>UB与UB</td><td>连续或高维切分复制</td><td><a href="ub_ub_data_move.html">UB与UB数据搬运</a></td></tr><tr><td>Reg与UB</td><td>对齐/非对齐加载、存储、广播、交织、压缩和Post Update</td><td><a href="reg_ub_data_move.html">Reg与UB数据搬运</a></td></tr></tbody></table><h2 id="接口选择原则">接口选择原则<a class="header-anchor" href="#接口选择原则">​</a></h2><ul><li>先按源、目的存储单元确定物理通路。NPU架构版本3510没有GM到L0A/L0B和L1到GM直达通路，不能只根据地址类型猜测接口。</li><li>一段连续数据优先选择连续原型；多个等长数据块之间存在固定间隔时选择高维切分原型；需要最多五维的Padding、Transpose、Broadcast或Slice时选择NDDMA。</li><li>GM与UB普通接口的长度以字节表示，只需满足数据类型字节对齐，不要因为有效长度不是32字节的整数倍就必然改用<code>*_align</code>接口。但GM到UB会在UB目的端补齐写入，UB到GM也会从UB读取补齐范围，因此UB仍需为32字节补齐后的实际访问范围预留空间。需要显式控制补齐布局、左右Padding或L2 Cache策略时，再选择对应的<code>*_align</code>高维切分原型。GM到L1的非32字节块长则使用<code>asc_copy_gm2l1_align</code>。</li><li>需要在搬运时改变矩阵排布、数据类型或执行量化激活时，选择具备随路处理能力的GM到L1或L0C搬出接口，并先完成配套寄存器配置。</li><li>数据生产者和消费者位于不同流水或不同执行核时，根据数据依赖显式同步；多条搬运写入重叠目的区域时，也需要保证串行化。</li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>建议在Kernel入口首先调用<a href="../utils/sys_init/asc_init.html">asc_init</a>，再进行数据搬运和计算。配置接口设置的Padding、循环、格式转换、量化和激活状态可能影响后续指令，复用前应按当前任务重新确认。</p></div></article></div>',1)])])}const p=a(l,[["render",_]]);export{n as __pageData,p as default};
